import os
from flask import Flask, request, render_template, send_from_directory

app = Flask(__name__)
app.config['UPLOAD_FOLDER'] = '/tmp/uploads'
app.config['OUTPUT_FOLDER'] = '/tmp/output'

ALLOWED_EXTENSIONS = {'png', 'jpg', 'jpeg', 'gif'}

def allowed_file(filename):
    # Only checks file extension, not the filename itself for path traversal characters
    return '.' in filename and filename.rsplit('.', 1)[1].lower() in ALLOWED_EXTENSIONS

@app.route('/', methods=['GET', 'POST'])
def upload_file():
    if request.method == 'POST':
        if 'file' not in request.files:
            return render_template('index.html', msg='No file selected')

        file = request.files['file']

        if file.filename == '':
            return render_template('index.html', msg='No selected file')

        if file and allowed_file(file.filename):
            filename = file.filename
            # VULNERABLE: Using ".." with os.path.join allows path traversal to escape /tmp directory
            upload_path = os.path.join("/tmp", "..", filename)
